  if not exists (select 1 from reading_passages where title = $q$Sixpence and a Serious Book$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Sixpence and a Serious Book$q$, $q$Cheap books in paper covers existed long before the twentieth century, but they were usually badly printed and badly regarded. Railway stalls sold sensational stories on rough paper, and respectable publishers kept their distance from them. A serious book was expected to be a hardback, and its price put it beyond most household budgets. Libraries and lending clubs filled the gap for readers who could not afford to buy. The idea that a good new novel might cost about the same as a packet of cigarettes seemed unlikely.

In 1935 Allen Lane, an English publisher, launched a series called Penguin Books at sixpence a volume. The list mixed novels, crime stories and serious non-fiction, and the covers used plain colour bands instead of pictures. The colour indicated the category, so a buyer could recognise a Penguin thriller from across a crowded shop. Booksellers were unenthusiastic about the experiment, and the series was rescued by a large order from the Woolworths chain. Within a year Penguin had sold millions of copies, and other publishers hurried to imitate the format.

The paperback changed who read books and where reading actually happened. Books were now bought in chemists, railway stations and department stores rather than only in specialist bookshops. Soldiers in the Second World War were supplied with paperbacks designed to fit a uniform pocket. Publishers discovered that there was a large audience for serious writing which the hardback trade had never reached. Paper covers were not new, however, and the real innovation was respectability: good books sold cheaply, without apology.$q$, $q$culture / media$q$, 3, 257, true, $q$reading_shabbat_2026-09-05_E2$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, how were cheap paper-covered books regarded before the twentieth century?$q$, $q$["As badly produced reading matter that serious publishers preferred to avoid.", "As the standard format for new novels by respected authors.", "As too expensive for the ordinary household to buy regularly.", "As the main source of income for public lending libraries."]$q$::jsonb, 0, $q$["נכון. הפסקה כותבת שהספרים הזולים היו מודפסים גרוע ונחשבו נחותים, ושמוציאים לאור מכובדים שמרו מהם מרחק.", "לא נכון. הפסקה מציינת שספר רציני היה אמור להיות בכריכה קשה.", "לא נכון. המחיר הגבוה מיוחס בפסקה לכריכה הקשה, לא לספרים בכריכה רכה.", "לא נכון. הספריות מוזכרות כפתרון לקוראים שלא יכלו לקנות, ולא כמי שהתפרנסו מספרים אלה."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, null, $q$shabbat batch E2, passage=paperback-revolution, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["explain why hardbacks remained beyond most household budgets.", "describe the paperbacks that were supplied to soldiers during the war.", "argue that colour is more useful than pictures on a book cover.", "recount how Penguin was launched and how quickly it succeeded."]$q$::jsonb, 3, $q$["לא נכון. זהו תוכן הפסקה הראשונה — מחיר הכריכה הקשה — ולא הפסקה השנייה.", "לא נכון. זהו תוכן הפסקה האחרונה — הספרים לחיילים — ולא הפסקה השנייה.", "לא נכון. הפסקה מתארת את פסי הצבע ככלי זיהוי, אך אינה טוענת שהם עדיפים על תמונות באופן כללי.", "נכון. הפסקה השנייה מספרת על השקת פינגווין ב-1935, על הצלת הסדרה בזכות הזמנת וולוורת'ס ועל מיליוני העותקים שנמכרו בתוך שנה."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch E2, passage=paperback-revolution, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The passage states that the series "was rescued by a large order from the Woolworths chain." This was necessary because —$q$, $q$["the first Penguin titles had been printed with serious errors.", "ordinary booksellers had shown little enthusiasm for the series.", "Allen Lane had run out of suitable books to include in the list.", "the colour bands on the covers had confused most early buyers."]$q$::jsonb, 1, $q$["לא נכון. הפסקה אינה מזכירה טעויות דפוס כלשהן.", "נכון. אותו משפט עצמו פותח בכך שהמוכרים הרגילים לא גילו התלהבות מהניסוי, ולכן ההזמנה הגדולה הצילה את הסדרה.", "לא נכון. הפסקה מציינת שהרשימה כללה רומנים, ספרי מתח ועיון רציני.", "לא נכון. הפסקה כותבת שפסי הצבע דווקא סייעו לקונים לזהות את סוג הספר."]$q$::jsonb, $q$explicit_detail$q$, $q$anchor$q$, $q$["the series was rescued by a large order from the Woolworths chain"]$q$::jsonb, $q$shabbat batch E2, passage=paperback-revolution, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the last paragraph, the word "respectability" most nearly means —$q$, $q$["The ability to be sold at a very low price", "The habit of reading books in public places", "A cover design that uses colour instead of pictures", "The status of being taken seriously by readers"]$q$::jsonb, 3, $q$["לא נכון. המחיר הנמוך אינו החידוש לפי הפסקה, שהרי כריכות נייר זולות כבר היו קיימות.", "לא נכון. המילה אינה מתארת היכן קוראים אלא כיצד נתפסים הספרים.", "לא נכון. עיצוב הכריכה מתואר בפסקה השנייה ואינו משמעות המילה.", "נכון. 'respectability' פירושו מעמד של דבר הנחשב רציני ומכובד — כאן ספרים טובים שנמכרו בזול בלי להתנצל."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["the real innovation was respectability"]$q$::jsonb, $q$shabbat batch E2, passage=paperback-revolution, q4$q$, 4, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$Based on the passage, what can be inferred about the audience for serious books before 1935?$q$, $q$["It consisted mainly of soldiers and of railway travellers.", "It was shrinking because of competition from cheap newspapers.", "It was larger than publishers had realised.", "It preferred crime stories to any other kind of writing."]$q$::jsonb, 2, $q$["לא נכון. החיילים מופיעים רק בהקשר של מלחמת העולם השנייה, לאחר 1935.", "לא נכון. הקטע אינו מזכיר תחרות מצד עיתונים ואינו טוען שקהל הקוראים הצטמצם.", "נכון. הפסקה האחרונה כותבת שהמוציאים לאור גילו קהל גדול לכתיבה רצינית שסחר הכריכה הקשה מעולם לא הגיע אליו — כלומר הקהל היה קיים אך לא זוהה.", "לא נכון. ספרי המתח הם רק אחד מסוגי הספרים ברשימת פינגווין, והקטע אינו מדרג העדפות."]$q$::jsonb, $q$inference$q$, $q$text$q$, null, $q$shabbat batch E2, passage=paperback-revolution, q5$q$, 5, true);
  end if;

  if not exists (select 1 from reading_passages where title = $q$Reading or Hearing a Foreign Film$q$) then
    insert into reading_passages(title, body, topic, difficulty, word_count, is_published, generation_batch)
      values ($q$Reading or Hearing a Foreign Film$q$, $q$Silent films crossed borders easily, since a printed title card could be replaced in any language for very little money. The arrival of synchronised sound at the end of the 1920s ended that freedom almost overnight. Studios briefly tried shooting the same film several times with different casts, an expensive method that satisfied nobody. Two solutions replaced it, and the choice between them hardened into national habit within a decade. Subtitles were cheap and quick to produce, while dubbing was costly but left the image uninterrupted.

Cost alone does not explain the pattern that eventually emerged across Europe. Small markets with high literacy, such as the Netherlands and the Nordic countries, adopted subtitles and kept them. Larger markets with strong national film industries, including Germany, Italy, Spain and France, built dubbing studios instead. Political motives reinforced the economic ones, since authoritarian governments in the 1930s preferred a version of a foreign film they could rewrite. Audiences then grew up with one convention and came to find the other distracting.

These inherited habits still shape which films travel abroad and how they are received there. A subtitled film reaches viewers with the original performance intact, yet it asks them to read while they watch. Dubbing removes that effort but replaces the actor's voice, which is a large part of a performance. Distributors know this, and a film with dense dialogue is harder to sell into a dubbing market than a film built on action. Streaming services now offer both options on the same title, although national preferences have proved surprisingly durable.$q$, $q$culture / media$q$, 6, 260, true, $q$reading_shabbat_2026-09-05_E2$q$)
      returning id into v_pid;
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$According to the first paragraph, all of the following are true EXCEPT —$q$, $q$["Title cards in silent films could be translated cheaply for foreign markets.", "Studios briefly filmed the same story several times with different casts.", "Dubbing cost more than subtitling but left the picture undisturbed.", "Subtitling was invented before synchronised sound reached the cinema."]$q$::jsonb, 3, $q$["לא נכון. זו קביעה נכונה על פי הפסקה, ולכן אינה החריג המבוקש — כרטיסיות הכיתוב אכן הוחלפו בזול בכל שפה.", "לא נכון. זו קביעה נכונה על פי הפסקה, ולכן אינה החריג המבוקש — האולפנים אכן צילמו את אותו סרט כמה פעמים עם צוותי שחקנים שונים.", "לא נכון. זו קביעה נכונה על פי הפסקה, ולכן אינה החריג המבוקש — הדיבוב אכן היה יקר יותר אך השאיר את התמונה שלמה.", "נכון. זו הקביעה השגויה — הפסקה מציגה את הכתוביות כאחד משני הפתרונות שהופיעו אחרי בוא הקול, ולא לפניו."]$q$::jsonb, $q$explicit_detail$q$, $q$paragraph$q$, $q$["Two solutions replaced it, and the choice between them hardened into national habit within a decade"]$q$::jsonb, $q$shabbat batch E2, passage=subtitles-dubbing, q1$q$, 1, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$The main purpose of the second paragraph is to —$q$, $q$["describe the multi-language versions that studios abandoned in the 1930s.", "explain why different countries settled on different translation methods.", "show how streaming services now offer viewers a choice of both options.", "argue that dubbing damages the performance an actor originally gave."]$q$::jsonb, 1, $q$["לא נכון. הגרסאות הרב-לשוניות מתוארות בפסקה הראשונה, ולא בשנייה.", "נכון. הפסקה השנייה מונה את הגורמים — גודל השוק, אוריינות, תעשיית קולנוע מקומית ומניעים פוליטיים — שהובילו מדינות שונות לבחירות שונות.", "לא נכון. זהו תוכן הפסקה האחרונה — שירותי הסטרימינג — ולא הפסקה השנייה.", "לא נכון. הטענה על קולו של השחקן מופיעה בפסקה האחרונה, והפסקה השנייה אינה מכריעה בין השיטות."]$q$::jsonb, $q$paragraph_purpose$q$, $q$paragraph$q$, null, $q$shabbat batch E2, passage=subtitles-dubbing, q2$q$, 2, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the sentence "Audiences then grew up with one convention and came to find the other distracting," the phrase "the other" refers to —$q$, $q$["the translation method their own country had not adopted", "the original language of the imported film", "the political motives of governments in the 1930s", "the national film industry of a larger market"]$q$::jsonb, 0, $q$["נכון. הפסקה מציגה שתי שיטות תרגום, ולכן 'the other' הוא השיטה השנייה — זו שהמדינה של אותם צופים לא אימצה.", "לא נכון. שפת המקור אינה אחת משתי המוסכמות שהפסקה מעמידה זו מול זו.", "לא נכון. המניעים הפוליטיים מוזכרים במשפט הקודם כסיבה, ואינם 'המוסכמה האחרת'.", "לא נכון. תעשיית הקולנוע המקומית היא גורם שהשפיע על הבחירה, ולא שיטת התרגום עצמה."]$q$::jsonb, $q$reference_word$q$, $q$anchor$q$, $q$["Audiences then grew up with one convention and came to find the other distracting."]$q$::jsonb, $q$shabbat batch E2, passage=subtitles-dubbing, q3$q$, 3, true);
    insert into reading_questions(passage_id, question_text, options, correct_option_index, explanations_he, question_type, window_size, highlight_spans, qa_note, display_order, is_published)
      values (v_pid, $q$In the last paragraph, the word "durable" is closest in meaning to —$q$, $q$["Expensive to maintain over a long period of time", "Difficult for outsiders to understand clearly", "Shared by audiences in every European country", "Lasting rather than quickly disappearing"]$q$::jsonb, 3, $q$["לא נכון. המילה אינה עוסקת בעלות אחזקה.", "לא נכון. המילה אינה עוסקת במידת המובנוּת של ההעדפות.", "לא נכון. הפסקה השנייה מדגישה שההעדפות שונות ממדינה למדינה, ולא משותפות לכולן.", "נכון. 'durable' פירושו מתמיד ועמיד — ההעדפות הלאומיות שרדו גם כששירותי הסטרימינג הציעו את שתי האפשרויות."]$q$::jsonb, $q$vocab_in_context$q$, $q$anchor$q$, $q$["national preferences have proved surprisingly durable"]$q$::jsonb, $q$shabbat batch E2, passage=subtitles-dubbing, q4$q$, 4, true);
